package com.selimhorri.app.exception.wrapper;

public class PaymentNotFoundException extends RuntimeException {

    private static final long serialVersionUID = 1L;

    public PaymentNotFoundException() {
        super();
    }

    public PaymentNotFoundException(String message, Throwable cause) {
        super(message, cause);
    }

    public PaymentNotFoundException(String message) {
        super(message);
    }

    public PaymentNotFoundException(Throwable cause) {
        super(cause);
    }
}

package com.selimhorri.app.helper;

import com.selimhorri.app.domain.Payment;
import com.selimhorri.app.dto.OrderDto;
import com.selimhorri.app.dto.PaymentDto;

public interface PaymentMappingHelper {

    public static PaymentDto map(final Payment payment) {
        return PaymentDto.builder().paymentId(payment.getPaymentId()).isPayed(payment.getIsPayed()).paymentStatus(payment.getPaymentStatus()).orderDto(OrderDto.builder().orderId(payment.getOrderId()).build()).build();
    }

    public static Payment map(final PaymentDto paymentDto) {
        return Payment.builder().paymentId(paymentDto.getPaymentId()).orderId(paymentDto.getOrderDto().getOrderId()).isPayed(paymentDto.getIsPayed()).paymentStatus(paymentDto.getPaymentStatus()).build();
    }
}

